const tabId = 730410078;
const nextDataSearch = await browserjs(tabId, () => {
  if (!window.__next_f) return "No __next_f";
  const allChunks = window.__next_f.map(item => item[1] || "").join("\n");

  // Look for occurrences of "flu", "risk", "level", "index", "champaign"
  const matches = [];
  const lines = allChunks.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (/flu|influenza|cold/i.test(line)) {
      matches.push(line.slice(0, 300));
    }
  }
  return {
    totalChunks: window.__next_f.length,
    matchesCount: matches.length,
    sampleMatches: matches.slice(0, 20)
  };
});
