const tabId = 730410078;
const scriptTexts = await browserjs(tabId, () => {
  const scripts = Array.from(document.querySelectorAll('script'));
  const fluRelated = [];
  for (const s of scripts) {
    if (s.textContent && /flu|influenza|risk/i.test(s.textContent)) {
      fluRelated.push(s.textContent);
    }
  }
  return {
    count: fluRelated.length,
    snippets: fluRelated.map(t => {
      // Find where "flu" or "risk" appears
      const idx = t.search(/flu/i);
      return t.slice(Math.max(0, idx - 100), Math.min(t.length, idx + 400));
    })
  };
});
