const tabId = 730410078;
const fiberData = await browserjs(tabId, () => {
  // Try to find React fiber on the map or forecast container
  const container = document.querySelector('[id^="pangea-map"]') || document.querySelector('section');
  if (!container) return "No container";

  // Traverse DOM around Extended 15 Day Flu Forecast
  const heading = Array.from(document.querySelectorAll('h2')).find(h => h.textContent.includes('Extended 15 Day Flu Forecast'));
  const parent = heading ? heading.closest('section') || heading.parentElement.parentElement : null;

  // Check React props/fiber
  function getReactProps(node) {
    if (!node) return null;
    const key = Object.keys(node).find(k => k.startsWith('__reactFiber') || k.startsWith('__reactInternalInstance'));
    if (!key) return null;
    return node[key];
  }

  let current = parent;
  let propsFound = [];
  while (current && propsFound.length < 5) {
    const fiber = getReactProps(current);
    if (fiber) {
      // Look up fiber tree for memoizedProps
      let f = fiber;
      while (f) {
        if (f.memoizedProps) {
          const keys = Object.keys(f.memoizedProps);
          if (keys.some(k => /flu|risk|forecast|data|layer/i.test(k))) {
            propsFound.push({
              tag: f.elementType?.name || f.tag,
              props: f.memoizedProps
            });
          }
        }
        f = f.return;
      }
      break;
    }
    current = current.parentElement;
  }
  return {
    propsFoundCount: propsFound.length,
    props: propsFound.slice(0, 3)
  };
});
console.log(JSON.stringify(fiberData, null, 2));

